// burnup-data.js
// Structure for a release burn-up chart

const burnUpData = {
  release: "Q2 2025 Payment Platform",
  startDate: "2025-04-01",
  endDate: "2025-06-30",

  // Sprint data
  sprints: [
    { 
      number: 1,
      endDate: "2025-04-15",
      totalScope: 120,
      completed: 18,
      scopeChanges: []
    },
    { 
      number: 2,
      endDate: "2025-04-29",
      totalScope: 120,
      completed: 35,
      scopeChanges: []
    },
    { 
      number: 3,
      endDate: "2025-05-13",
      totalScope: 135,
      completed: 48,
      scopeChanges: [
        { type: "added", points: 15, description: "Apple Pay integration" }
      ]
    },
    { 
      number: 4,
      endDate: "2025-05-27",
      totalScope: 135,
      completed: 62,
      scopeChanges: []
    },
    { 
      number: 5,
      endDate: "2025-06-10",
      totalScope: 145,
      completed: 78,
      scopeChanges: [
        { type: "added", points: 10, description: "Fraud check requirement" }
      ]
    },
    { 
      number: 6,
      endDate: "2025-06-24",
      totalScope: 145,
      completed: 102,
      scopeChanges: []
    }
  ],

  // Calculate derived data
  get remainingWork: function() {
    const latest = this.sprints[this.sprints.length - 1];
    return latest.totalScope - latest.completed;
  },

  get averageVelocity: function() {
    // Skip sprint 0, average completed points per sprint
    const completedPoints = this.sprints.map(s => s.completed);
    const deltas = [];
    for (let i = 1; i < completedPoints.length; i++) {
      deltas.push(completedPoints[i] - completedPoints[i-1]);
    }
    return deltas.reduce((a, b) => a + b, 0) / deltas.length;
  },

  get forecast: function() {
    const remaining = this.remainingWork();
    const velocity = this.averageVelocity();
    const sprintsNeeded = Math.ceil(remaining / velocity);
    return {
      sprintsRemaining: sprintsNeeded,
      completionSprint: this.sprints.length + sprintsNeeded
    };
  }
};

// Export for dashboard use
module.exports = burnUpData;
